files.content:
html {
  block-size: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  background: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
  block-size: 100%;
}

div {
  background-image: conic-gradient(#6dc1fd, #feafe8, #6dc1fd);
  inline-size: 100%;
  block-size: 100%;
}
